CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS vehicles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), plate text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS vehicles_plate_unique ON vehicles (upper(plate)) WHERE plate IS NOT NULL;
CREATE TABLE IF NOT EXISTS parking_lots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, layout jsonb NOT NULL DEFAULT '[]', layout_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS parking_slots (id text NOT NULL, lot_id uuid NOT NULL REFERENCES parking_lots(id), zone text NOT NULL, tier text NOT NULL DEFAULT 'Standard', hourly_rate numeric(10,2) NOT NULL CHECK(hourly_rate >= 0), status text NOT NULL DEFAULT 'AVAILABLE', row_num integer NOT NULL, col_num integer NOT NULL, PRIMARY KEY(lot_id,id));
CREATE TABLE IF NOT EXISTS bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), vehicle_id uuid REFERENCES vehicles(id), lot_id uuid NOT NULL REFERENCES parking_lots(id), slot_id text NOT NULL, status text NOT NULL, start_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, entry_at timestamptz, exit_at timestamptz, entry_amount numeric(10,2) NOT NULL DEFAULT 0, exit_balance numeric(10,2) NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(lot_id,slot_id) REFERENCES parking_slots(lot_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS one_live_booking_per_slot ON bookings(lot_id,slot_id) WHERE status IN ('TEMP_HOLD','BOOKED','CHECKED_IN','EXTENDED','OVERSTAY','EXIT_PENDING_PAYMENT');
CREATE TABLE IF NOT EXISTS payment_transactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), stage text NOT NULL, amount numeric(10,2) NOT NULL CHECK(amount >= 0), currency char(3) NOT NULL DEFAULT 'USD', idempotency_key text NOT NULL UNIQUE, status text NOT NULL, provider_ref text, created_at timestamptz NOT NULL DEFAULT now());
